def compile_json_path(key_transforms, include_root=True):
    """
    Compile a JSON path expression from a sequence of key transforms.

    Numeric keys should only be treated as array indexes when the key is an
    integer type. String representations of numbers (e.g. "1111") represent
    object keys and must be quoted, otherwise lookups such as has_key on SQLite,
    MySQL, and Oracle will incorrectly treat them as array indexes.
    """
    path = ["$"] if include_root else []
    for key_transform in key_transforms:
        if isinstance(key_transform, int):
            # Array index.
            path.append("[%s]" % key_transform)
        else:
            # Object key – always quoted.
            path.append(".")
            path.append(json.dumps(key_transform))
    return "".join(path)
