class PyProperty(ObjectDescription):
    def handle_signature(self, sig: str, signode: desc_signature) -> Tuple[str, str]:
        # Use the generic function handling to get the basic signature parsing
        fullname, prefix = super().handle_signature(sig, signode)

        # Additionally parse the return annotation (type hint) for a property.
        # ``py_sig_re`` extracts the return annotation as the fourth group.
        m = py_sig_re.match(sig)
        if m:
            _, _, _, retann = m.groups()
            if retann:
                # Convert the annotation string into nodes (with cross‑references)
                children = _parse_annotation(retann, self.env)
                # ``desc_returns`` expects the raw source text as the first argument
                # and an empty title argument before the children.
                signode += addnodes.desc_returns(retann, '', *children)

        return fullname, prefix
